2000	/**
2001	 * Parse `nginx -T` (the source's FULLY MERGED, running configuration) into vhost
2002	 * intent.
2003	 *
2004	 * WHY intent and not the files: blind-copying the source's `/etc/nginx` over the
2005	 * target's is what broke a real cutover in seven separate ways. The source was
2006	 * HestiaCP on nginx 1.25; the target is stock Ubuntu nginx 1.18. The copy
2007	 * replaced the target's `nginx.conf` (so its `include sites-enabled/*` vanished
2008	 * and any vhost written there was silently ignored), carried `listen
2009	 * <old-ip>:80` into 21 files (`bind() to <old ip>:80 failed` — nginx would not
2010	 * start at all), referenced certificates and `options-ssl-nginx.conf` that do
2011	 * not exist here, used `http2 on;` which 1.18 rejects as an unknown directive,
2012	 * pointed at log directories that do not exist, and installed a catch-all
2013	 * default server proxying to a dead port that answered 502 for every request.
2014	 *
2015	 * So: read the source's intent, then GENERATE a clean configuration in the
2016	 * target's own dialect, leaving the target's nginx.conf and include layout
2017	 * untouched. The source tree is kept as a read-only reference copy for the
2018	 * customer instead of being installed.
2019	 */
2020	export function parseNginxDump(lines: string[]): SrcVhost[] {
2021	  const upstreams = new Map<string, number>();
2022	  const out: SrcVhost[] = [];
2023	  let depth = 0;
2024	  let cur: SrcVhost | null = null;
2025	  let curDepth = 0;
2026	  let upName = "";
2027	  let upDepth = -1;
2028	
2029	  for (const raw of lines) {
2030	    const line = clean(raw, 1000).trim();
2031	    if (!line || line.startsWith("#")) continue;
2032	    const opens = (line.match(/\{/g) ?? []).length;
2033	    const closes = (line.match(/\}/g) ?? []).length;
2034	    const d = line.replace(/;\s*$/, "").trim();
2035	
2036	    // upstream blocks, so `proxy_pass http://myapp` resolves to a real port.
2037	    // Both the multi-line and the `upstream x { server 1.2.3.4:80; }` one-liner
2038	    // shapes occur in real configs, so the inline body is scanned too.
2039	    const um = /^upstream\s+([A-Za-z0-9._-]{1,64})\s*\{/.exec(line);
2040	    if (!cur && um) {
2041	      upName = um[1];
2042	      upDepth = depth;
2043	      const inline = /(?:^|;|\{)\s*server\s+[A-Za-z0-9._-]+:(\d{1,5})/.exec(line.slice(um[0].length));
2044	      if (inline) {
2045	        const p = Number(inline[1]);
2046	        if (Number.isInteger(p) && p >= 1 && p <= 65535) upstreams.set(upName, p);
2047	      }
2048	      depth += opens - closes;
2049	      if (depth <= upDepth) {
2050	        upName = "";
2051	        upDepth = -1;
2052	      }
2053	      continue;
2054	    }
2055	    if (upName) {
2056	      const sm = /^server\s+([A-Za-z0-9._-]+):(\d{1,5})/.exec(d);
2057	      if (sm && !upstreams.has(upName)) {
2058	        const p = Number(sm[2]);
2059	        if (Number.isInteger(p) && p >= 1 && p <= 65535) upstreams.set(upName, p);
2060	      }
2061	      depth += opens - closes;
2062	      if (depth <= upDepth) {
2063	        upName = "";
2064	        upDepth = -1;
2065	      }
2066	      continue;
2067	    }
2068	
2069	    if (!cur && /^server\s*\{/.test(line)) {
2070	      cur = { names: [], wildcard: "", proxyPort: 0, root: "", ssl: false, isDefault: false, ports: [] };
2071	      curDepth = depth;
2072	      depth += opens - closes;
2073	      continue;
2074	    }
2075	
2076	    if (cur) {
