2078	      // independently rather than as an if/else chain: `nginx -T` reproduces the
2079	      // author's formatting, and one-liners like
2080	      // `location / { proxy_pass http://127.0.0.1:3720; }` are extremely common.
2081	      // Anchoring at the start silently loses the upstream and the site then
2082	      // looks unpublishable.
2083	      let m: RegExpExecArray | null;
2084	      if ((m = /(?:^|;|\{)\s*server_name\s+([^;{}]+)/.exec(d))) {
2085	        for (const t of m[1].split(/\s+/).slice(0, 12)) {
2086	          if (t === "_" || t === "localhost") {
2087	            cur.isDefault = true;
2088	            continue;
2089	          }
2090	          if (t.startsWith("*.")) {
2091	            const b = normalizeDomain(t.slice(2));
2092	            if (b) {
2093	              cur.wildcard = b;
2094	              if (!cur.names.includes(b)) cur.names.push(b);
2095	            }
2096	            continue;
2097	          }
2098	          const dm = normalizeDomain(t);
2099	          if (dm && !cur.names.includes(dm)) cur.names.push(dm);
2100	        }
2101	      }
2102	      if ((m = /(?:^|;|\{)\s*listen\s+([^;{}]+)/.exec(d))) {
2103	        const toks = m[1].trim().split(/\s+/);
2104	        const addr = toks[0];
2105	        let port = 0;
2106	        if (/^\d{1,5}$/.test(addr)) port = Number(addr);
2107	        else {
2108	          const pm = /^(?:\[[0-9a-fA-F:]+\]|[0-9.]+):(\d{1,5})$/.exec(addr);
2109	          if (pm) port = Number(pm[1]);
2110	        }
2111	        if (Number.isInteger(port) && port >= 1 && port <= 65535 && !cur.ports.includes(port)) cur.ports.push(port);
2112	        if (toks.includes("ssl") || port === 443) cur.ssl = true;
2113	        if (toks.includes("default_server") || toks.includes("default")) cur.isDefault = true;
2114	      }
2115	      if ((m = /(?:^|;|\{)\s*root\s+([^;{}\s]+)/.exec(d))) {
2116	        const p = m[1].replace(/\/$/, "");
2117	        if (validPath(p) && !cur.root) cur.root = p;
2118	      }
2119	      if ((m = /(?:^|;|\{)\s*proxy_pass\s+([^;{}\s]+)/.exec(d))) {
2120	        const pm = /^https?:\/\/([A-Za-z0-9._-]+)(?::(\d{1,5}))?/.exec(m[1]);
2121	        if (pm && !cur.proxyPort) {
2122	          if (pm[2]) {
2123	            const p = Number(pm[2]);
2124	            if (Number.isInteger(p) && p >= 1 && p <= 65535) cur.proxyPort = p;
2125	          } else {
2126	            const up = upstreams.get(pm[1]);
2127	            if (up) cur.proxyPort = up;
2128	          }
2129	        }
2130	      }
2131	      depth += opens - closes;
2132	      if (depth <= curDepth) {
2133	        if (cur.names.length) out.push(cur);
2134	        cur = null;
2135	      }
2136	      continue;
2137	    }
2138	
2139	    depth += opens - closes;
2140	    if (depth < 0) depth = 0;
2141	  }
2142	  return out;
2143	}
