2155	      if (pm) {
2156	        const p = Number(pm[1]);
2157	        if (Number.isInteger(p) && p >= 1 && p <= 65535) {
2158	          cur.ports.push(p);
2159	          if (p === 443) cur.ssl = true;
2160	        }
2161	      }
2162	      continue;
2163	    }
2164	    if (!cur) continue;
2165	    if (/^<\/VirtualHost/i.test(line)) {
2166	      if (cur.names.length) out.push(cur);
2167	      cur = null;
2168	      continue;
2169	    }
2170	    let m: RegExpExecArray | null;
2171	    if ((m = /^Server(?:Name|Alias)\s+(.+)$/i.exec(line))) {
2172	      for (const t of m[1].split(/\s+/).slice(0, 12)) {
2173	        if (t.startsWith("*.")) {
2174	          const b = normalizeDomain(t.slice(2));
2175	          if (b) {
2176	            cur.wildcard = b;
2177	            if (!cur.names.includes(b)) cur.names.push(b);
2178	          }
2179	          continue;
2180	        }
2181	        const dm = normalizeDomain(t);
2182	        if (dm && !cur.names.includes(dm)) cur.names.push(dm);
2183	      }
2184	    } else if ((m = /^DocumentRoot\s+"?([^"\s]+)"?$/i.exec(line))) {
2185	      const p = m[1].replace(/\/$/, "");
2186	      if (validPath(p)) cur.root = p;
2187	    } else if ((m = /^ProxyPass\s+\S+\s+(\S+)/i.exec(line))) {
2188	      const pm = /^https?:\/\/[A-Za-z0-9._-]+:(\d{1,5})/.exec(m[1]);
2189	      if (pm && !cur.proxyPort) {
2190	        const p = Number(pm[1]);
2191	        if (Number.isInteger(p) && p >= 1 && p <= 65535) cur.proxyPort = p;
2192	      }
2193	    } else if (/^SSLCertificateFile/i.test(line)) {
2194	      cur.ssl = true;
2195	    }
