781	/**
782	 * Idempotently ensure each allowlisted package is present on the target. Runs
783	 * `apt-get update` once, then for each key: skip if the check passes, else try
784	 * apt → dnf → yum with the FIXED package string. Returns which were newly
785	 * installed / already present / failed. Never throws (best-effort per package).
786	 *
787	 * `say` is optional so every existing call site keeps working unchanged; when it
788	 * is supplied the slow parts (metadata refresh + each install) narrate
789	 * themselves, because a package install is one of the three steps that can sit
790	 * silent for minutes (see withHeartbeat).
791	 */
792	async function ensurePackages(
793	  conn: Client,
794	  keys: PkgKey[],
795	  say?: (line: string) => Promise<void>
796	): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
797	  const beat = <T,>(what: string, run: () => Promise<T>): Promise<T> =>
798	    say ? withHeartbeat(what, say, run) : run();
799	  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
800	  if (keys.length === 0) return out;
801	  // `DEBIAN_FRONTEND=noninteractive` is NOT sufficient on Ubuntu 22.04+.
802	  // `needrestart` hooks dpkg's post-install phase and opens an interactive
803	  // "which services should be restarted?" prompt on a tty nobody is reading,
804	  // which wedges apt until INSTALL_TIMEOUT_MS expires.
805	  //
806	  // Seen live on a real migration (2026-07-25): installing certbot blocked on
807	  // /usr/lib/needrestart/dpkg-status for the FULL 10-minute timeout, which was
808	  // the entire HTTPS window — the run finished with soulpilates.com.vn and
809	  // srv1182755.hstgr.cloud still on plain HTTP. A hang here does not just cost
810	  // time, it silently costs certificates.
811	  //
812	  // NEEDRESTART_MODE=a answers that prompt automatically (restart what's needed);
813	  // NEEDRESTART_SUSPEND=1 disables the hook outright on versions that honour it.
814	  // The force-conf* options settle the OTHER classic apt prompt — "a config file
815	  // you modified has changed" — by keeping the existing file, which is the right
816	  // answer on a machine we are migrating INTO.
817	  const APT_ENV = "DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a NEEDRESTART_SUSPEND=1";
818	  const APT_OPTS = `-o Dpkg::Options::="--force-confdef" -o Dpkg::Options::="--force-confold"`;
819	  // Refresh apt metadata once (best-effort; ignored on non-apt systems). Also
820	  // finish any dpkg run a previous interrupted install left half-configured —
821	  // otherwise every later apt call inherits the wedge.
822	  await beat("finishing any half-configured package install", () =>
823	    execRemote(conn, `${APT_ENV} dpkg --configure -a >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
824	  );
825	  await beat("refreshing the package index (apt-get update)", () =>
826	    execRemote(conn, `${APT_ENV} apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
827	  );
828	  for (const key of keys) {
829	    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
830	    if (already) {
831	      out.push({ key, ok: true, already: true });
832	      continue;
833	    }
834	    // Docker is special-cased: install via the OFFICIAL convenience script — the
835	    // SAME method the platform's own provisioning uses (buildCloudInit in
836	    // worker/index.ts). The apt/dnf package list fails on Ubuntu because
837	    // `docker-compose-plugin` isn't in Ubuntu's default apt repo, so the whole
838	    // install returned non-zero and Docker never came up. get.docker.com adds
839	    // Docker's own repo and installs docker-ce + the compose plugin across
840	    // Debian/Ubuntu/RHEL. The command is a FIXED constant (no source input);
841	    // still best-effort + logged like every other package.
842	    const install =
843	      key === "docker"
844	        ? `curl -fsSL https://get.docker.com | sh && systemctl enable --now docker`
845	        : `${APT_ENV} apt-get install -y ${APT_OPTS} ${PKG_APT[key]} ` +
846	          `|| dnf install -y ${PKG_DNF[key]} ` +
847	          `|| yum install -y ${PKG_DNF[key]}`;
848	    const r = await beat(`installing ${PKG_LABEL[key]}`, () =>
849	      execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }))
850	    );
851	    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
852	    if (nowPresent) {
853	      out.push({ key, ok: true, already: false });
854	    } else {
855	      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
856	      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
857	    }
858	  }
859	  return out;
860	}
