/**
 * Parse a size token (nginx `64m`, PHP `128M`, a bare Apache `LimitRequestBody`
 * byte count) into whole megabytes. A unit-less value is treated as bytes, which
 * is what `LimitRequestBody` emits; k/m/g are honoured case-insensitively.
 * Returns 0 for anything unparseable. (FIX A4)
 */
function sizeToMb(v: string): number {
  const m = /^\s*(\d+)\s*([kKmMgG])?/.exec(String(v ?? ""));
  if (!m) return 0;
  const n = Number(m[1]);
  if (!Number.isFinite(n) || n < 0) return 0;
  switch ((m[2] ?? "").toLowerCase()) {
    case "g":
      return n * 1024;
    case "m":
      return n;
    case "k":
      return Math.ceil(n / 1024);
    default:
      return Math.ceil(n / (1024 * 1024)); // bytes
  }
}

/**
 * Discover the SOURCE's PHP major (e.g. "8.1") from its merged web-server config
 * without touching the source: real vhosts name the fpm socket
 * (`fastcgi_pass unix:/run/php/php8.1-fpm.sock`) or a `/etc/php/8.1/` path. Returns
 * "" when nothing php-shaped is present, so the caller can fall back to a source
 * probe or the target distro's default metapackage. (FIX WEB-1)
 */
function phpMajorFromConfig(lines: string[]): string {
  for (const raw of lines) {
    const l = String(raw ?? "");
    let m = /php[-/]?(?:fpm)?[-/]?(\d(?:\.\d)?)-fpm\.sock/i.exec(l) || /\/etc\/php\/(\d(?:\.\d)?)\//i.exec(l);
    if (m && /^\d(?:\.\d)?$/.test(m[1])) return m[1];
  }
  return "";
}

/**
 * Custom source directives the regenerated (clean) config deliberately does NOT
 * reproduce — verbatim install broke a real cutover, so the source tree is kept
 * only as reference. Detecting these lets us NAME the loss as a manual step
 * instead of dropping it silently. We only flag categories, never translate
 * them. (FIX WEB-3)
 */
const DROPPED_DIRECTIVE_RULES: { label: string; re: RegExp }[] = [
  { label: "URL rewrite rules", re: /(?:^|[\s{;])(?:rewrite\s|RewriteRule|RewriteCond)/i },
  { label: "custom response headers (e.g. security headers)", re: /(?:^|[\s{;])(?:add_header|Header\s+(?:set|add|append|edit))/i },
  { label: "HTTP basic auth", re: /(?:^|[\s{;])(?:auth_basic|AuthType|AuthUserFile|Require\s+valid-user)/i },
  { label: "rate limiting", re: /(?:^|[\s{;])(?:limit_req|limit_conn|SetOutputFilter\s+RATE_LIMIT|mod_ratelimit)/i },
  { label: "custom error pages", re: /(?:^|[\s{;])(?:error_page|ErrorDocument)\b/i },
  { label: "explicit redirects", re: /(?:^|[\s{;])(?:return\s+30[1278]|rewrite\s+.*\bredirect\b|RedirectMatch|Redirect\s+(?:30\d|permanent|temp))/i },
];
function detectDroppedDirectives(lines: string[]): string[] {
  const found = new Set<string>();
  for (const raw of lines) {
    const l = String(raw ?? "");
    for (const r of DROPPED_DIRECTIVE_RULES) if (r.re.test(l)) found.add(r.label);
  }
  return [...found];
}

