/**
 * Install php-fpm on a Debian/Ubuntu (apt) target and return its real fpm socket,
 * so a migrated PHP doc-root (WordPress/Laravel/plain PHP) is actually executed
 * instead of collapsing to `try_files … =404` — the silent failure that hit every
 * PHP site whenever the target did not already happen to run php-fpm. (FIX WEB-1)
 *
 * `major` is the SOURCE's PHP major ("8.1") when we could discover it. It is
 * strictly validated (`\d` or `\d.\d`) before it ever reaches a shell, and it is
 * only an OPTIMISTIC first attempt: a specific major is frequently absent from the
 * target distro's default apt repo (Ubuntu 24.04 ships 8.3, not 8.1, without a
 * PPA), so we always fall back to the unversioned `php-fpm` metapackage, which
 * resolves to whatever current stable the distro provides. The resulting socket
 * is read back from disk (`/run/php/php*-fpm.sock`) rather than assumed, so it is
 * correct regardless of which major actually installed.
 *
 * Non-apt targets, or an install that produces no socket, return ok:false so the
 * caller can HONESTLY refuse — name the missing `php<major>-fpm` — never serve the
 * site as a silent 404.
 */
async function ensurePhpFpm(
  conn: Client,
  major: string,
  say?: (line: string) => Promise<void>
): Promise<{ ok: boolean; socket: string; label: string; reason?: string }> {
  const beat = <T,>(what: string, run: () => Promise<T>): Promise<T> => (say ? withHeartbeat(what, say, run) : run());
  const validMajor = /^\d(?:\.\d)?$/.test(major) ? major : "";
  const label = validMajor ? `php${validMajor}-fpm` : "php-fpm";

  // php-fpm is only installed here on apt targets, matching the existing runtime
  // install path; anything else is refused rather than guessed.
  const isApt = await shOk(conn, `command -v apt-get >/dev/null 2>&1`);
  if (!isApt) return { ok: false, socket: "", label, reason: "non-apt" };

  const APT_ENV = "DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a NEEDRESTART_SUSPEND=1";
  const APT_OPTS = `-o Dpkg::Options::="--force-confdef" -o Dpkg::Options::="--force-confold"`;
  await beat("finishing any half-configured package install", () =>
    execRemote(conn, `${APT_ENV} dpkg --configure -a >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
  );
  await beat("refreshing the package index (apt-get update)", () =>
    execRemote(conn, `${APT_ENV} apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => ({ code: 0, stdout: "", stderr: "" }))
  );

  const exts = (m: string) =>
    `php${m}-fpm php${m}-mysql php${m}-cli php${m}-curl php${m}-gd php${m}-mbstring php${m}-xml php${m}-zip`;
  // Prefer the source's major, then fall back to the distro's default metapackages.
  const attempts = [...(validMajor ? [exts(validMajor)] : []), "php-fpm php-mysql php-cli php-curl php-gd php-mbstring php-xml php-zip"];

  for (const pkgs of attempts) {
    await beat(`installing PHP (${pkgs.split(" ")[0]})`, () =>
      execRemote(conn, `${APT_ENV} apt-get install -y ${APT_OPTS} ${pkgs}`, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }))
    );
    // Enable + start whichever versioned fpm unit the install produced, then read
    // the socket back off disk — never assume the major that actually landed.
    const sock = clean(
      (
        await sh(
          conn,
          `svc=$(systemctl list-unit-files --type=service 2>/dev/null | awk '/^php[0-9.]*-fpm\\.service/{print $1; exit}'); ` +
            `[ -n "$svc" ] && systemctl enable --now "$svc" >/dev/null 2>&1; ` +
            `ls -1 /run/php/php*-fpm.sock /var/run/php/php*-fpm.sock 2>/dev/null | head -n1`,
          SETUP_TIMEOUT_MS
        )
      ).stdout,
      255
    );
    if (validPath(sock)) return { ok: true, socket: sock, label: pkgs.split(" ")[0] };
  }
  return { ok: false, socket: "", label, reason: "install-failed" };
}

