// 10c-A4. Carry the SOURCE's real upload ceiling instead of a blanket 64m.
// A WordPress/Nextcloud/Laravel site whose old server allowed 512m uploads
// would start rejecting large media/imports at 64m with a bare 413. Read the
// limit from the merged nginx config (free, in memory), the kept Apache
// reference tree, and any php.ini/.htaccess/.user.ini overrides in the copied
// doc-roots; keep the max, capped at 4g. Nothing found ⇒ leave 64m. (FIX A4)
if (servedSites.length) {
  let uploadMb = 0;
  for (const l of inv.nginxDump) {
    const m = /client_max_body_size\s+(\d+[kKmMgG]?)/i.exec(l);
    if (m) uploadMb = Math.max(uploadMb, m[1] === "0" ? 4096 : sizeToMb(m[1]));
  }
  const docRoots = [...new Set(servedSites.filter((s) => s.root).map((s) => s.root))];
  const iniTargets = docRoots.flatMap((r) => [`${r}/.htaccess`, `${r}/.user.ini`, `${r}/php.ini`]).join(" ");
  const grepSrc = `grep -rhiE 'LimitRequestBody|client_max_body_size|upload_max_filesize|post_max_size' ${refDir} ${iniTargets} 2>/dev/null | head -n 400`;
  const rawLimits = (await sh(conn, grepSrc)).stdout;
  for (const l of rawLimits.split("\n")) {
    let m: RegExpExecArray | null;
    if ((m = /LimitRequestBody\s+(\d+)/i.exec(l))) uploadMb = Math.max(uploadMb, sizeToMb(m[1]));
    if ((m = /client_max_body_size\s+(\d+[kKmMgG]?)/i.exec(l))) uploadMb = Math.max(uploadMb, m[1] === "0" ? 4096 : sizeToMb(m[1]));
    if ((m = /(?:upload_max_filesize|post_max_size)\s*[=:\s]\s*['"]?(\d+[kKmMgG]?)/i.exec(l))) uploadMb = Math.max(uploadMb, sizeToMb(m[1]));
  }
  uploadMb = Math.min(uploadMb, 4096);
  if (uploadMb > 64) for (const s of servedSites) s.maxBodyMb = uploadMb;
}

// 10c-WEB1. PHP apps need php-fpm actually installed and the socket wired.
// Until now `phpSocket` was set ONLY when php-fpm already happened to run on
// the target, so a migrated WordPress/Laravel/plain-PHP doc-root whose target
// had no php-fpm silently collapsed to `try_files … =404` — PHP served as
// static/404. Detect a PHP doc-root (its copied tree contains *.php /
// composer.json / artisan), install php-fpm on Debian/Ubuntu targets (source's
// PHP major preferred, distro default as fallback), and wire the resolved
// socket. If it cannot be installed, REFUSE honestly and name the step rather
// than serve a silent 404. (FIX WEB-1)
if (servedSites.length && !phpSocket) {
  const docRootSites = servedSites.filter((s) => s.root && !s.proxyPort);
  const phpSites: TargetSite[] = [];
  for (const s of docRootSites) {
    const hit = clean(
      (await sh(conn, `find ${s.root} -maxdepth 2 \\( -name '*.php' -o -name composer.json -o -name artisan \\) -print -quit 2>/dev/null`)).stdout,
      255
