    if (hit) phpSites.push(s);
  }
  if (phpSites.length) {
    // SOURCE major: from the merged web config first (no source round-trip),
    // then a read-only `php -v` on the source, else "" ⇒ distro default.
    let phpMajor = phpMajorFromConfig(inv.nginxDump);
    if (!phpMajor) {
      const pv = clean((await sh(conn, `${onSource(`php -v 2>/dev/null | head -n1`)} 2>/dev/null`, SETUP_TIMEOUT_MS)).stdout, 120);
      const pm = /PHP\s+(\d+\.\d+)/i.exec(pv);
      if (pm) phpMajor = pm[1];
    }
    await report(84, "Publishing your site…", "  A PHP site was detected — installing php-fpm so it runs, not 404s.");
    const fpm = await ensurePhpFpm(conn, phpMajor, (l) => report(84, "Publishing your site…", l));
    if (fpm.ok && fpm.socket) {
      for (const s of phpSites) s.phpSocket = fpm.socket;
      push({
        step: `PHP runtime for ${phpSites.length} site(s)`,
        status: "running",
        detail: `${phpSites.map((s) => s.names[0]).slice(0, 6).join(", ")} ${phpSites.length === 1 ? "is a PHP app" : "are PHP apps"} — installed ${fpm.label} and wired ${fpm.socket} so PHP is executed instead of served as a 404`,
      });
    } else {
      for (const s of phpSites) {
